/* ============================================
   GreenBean Coffee — Global Styles
   ============================================ */

/* CSS Custom Properties (Design Tokens) */
:root {
  --color-primary: #00824A;
  --color-primary-dark: #006b3d;
  --color-forest: #32462F;
  --color-cream: #F3CEA1;
  --color-cream-light: #FDF6EC;
  --color-white: #FFFFFF;
  --color-black: #1a1a1a;
  --color-gray-50: #FAFAFA;
  --color-gray-100: #F5F5F5;
  --color-gray-200: #E5E5E5;
  --color-gray-300: #D4D4D4;
  --color-gray-400: #A3A3A3;
  --color-gray-500: #737373;
  --color-gray-600: #525252;
  --color-gray-700: #404040;
  --color-gray-800: #262626;
  --color-gray-900: #171717;

  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-display: 'DM Sans', 'Inter', sans-serif;

  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background-color: var(--color-white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-gray-900);
}

.text-display {
  font-family: var(--font-display);
  font-weight: 700;
}

.text-body {
  font-family: var(--font-body);
}

/* ============================================
   Layout Utilities
   ============================================ */

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

@media (min-width: 768px) {
  .container {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: 3rem;
    padding-right: 3rem;
  }
}

/* ============================================
   Header
   ============================================ */

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--color-primary);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: 0.875rem;
}

.main-nav {
  display: none;
}

.main-nav ul {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.main-nav a {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
  position: relative;
}

.main-nav a:hover,
.main-nav a.active {
  color: var(--color-primary);
}

.main-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-primary);
  border-radius: var(--radius-full);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-gray-700);
  border: 1.5px solid var(--color-gray-300);
}

.btn-outline:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.btn-ghost {
  background: transparent;
  color: var(--color-gray-700);
}

.btn-ghost:hover {
  color: var(--color-primary);
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  color: var(--color-gray-700);
}

@media (min-width: 768px) {
  .main-nav {
    display: block;
  }
  .mobile-menu-btn {
    display: none;
  }
}

/* Mobile Menu */
.mobile-menu {
  display: none;
  position: absolute;
  top: 64px;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
  padding: 1.5rem;
  box-shadow: var(--shadow-lg);
}

.mobile-menu.open {
  display: block;
}

.mobile-menu ul {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.mobile-menu a {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-gray-700);
  padding: 0.5rem 0;
  display: block;
}

.mobile-menu a:hover,
.mobile-menu a.active {
  color: var(--color-primary);
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-forest) 0%, #1a2e16 100%);
  overflow: hidden;
}

.hero-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.06;
  background-image: radial-gradient(circle at 2px 2px, white 1px, transparent 0);
  background-size: 32px 32px;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
  padding: 3rem 0;
}

.hero h1 {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  color: var(--color-white);
  margin-bottom: 1.25rem;
  line-height: 1.1;
}

.hero p {
  font-size: 1.125rem;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 2rem;
  max-width: 480px;
}

.hero-visual {
  position: absolute;
  right: -5%;
  top: 50%;
  transform: translateY(-50%);
  width: 45%;
  max-width: 520px;
  aspect-ratio: 1;
  display: none;
}

.hero-visual-inner {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 40%, var(--color-cream) 0%, var(--color-primary) 60%, var(--color-forest) 100%);
  opacity: 0.25;
  filter: blur(40px);
}

@media (min-width: 1024px) {
  .hero-visual {
    display: block;
  }
}

/* ============================================
   Section Styles
   ============================================ */

.section {
  padding: 4rem 0;
}

.section-lg {
  padding: 5rem 0;
}

.section-cream {
  background: var(--color-cream-light);
}

.section-green {
  background: linear-gradient(135deg, var(--color-forest) 0%, #1a2e16 100%);
  color: var(--color-white);
}

.section-green h2,
.section-green h3 {
  color: var(--color-white);
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 3rem;
}

.section-header h2 {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  margin-bottom: 0.75rem;
}

.section-header p {
  font-size: 1.0625rem;
  color: var(--color-gray-500);
}

/* ============================================
   Cards
   ============================================ */

.card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-gray-200);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-media {
  aspect-ratio: 16 / 10;
  background: linear-gradient(135deg, var(--color-cream) 0%, var(--color-gray-200) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.card-media::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(0, 130, 74, 0.08) 0%, transparent 70%);
}

.card-media-icon {
  font-size: 3rem;
  opacity: 0.5;
}

.card-body {
  padding: 1.5rem;
}

.card-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--color-gray-900);
}

.card-text {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  margin-bottom: 1rem;
  line-height: 1.6;
}

/* ============================================
   Promo / Feature Blocks
   ============================================ */

.promo-block {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
  align-items: center;
}

.promo-block.reverse {
  direction: rtl;
}

.promo-block.reverse > * {
  direction: ltr;
}

.promo-visual {
  border-radius: var(--radius-2xl);
  overflow: hidden;
  background: linear-gradient(135deg, var(--color-cream) 0%, var(--color-gray-200) 100%);
  aspect-ratio: 4 / 3;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.promo-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(0, 130, 74, 0.06) 0%, transparent 70%);
}

.promo-visual-icon {
  font-size: 4rem;
  opacity: 0.4;
}

.promo-content h2 {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  margin-bottom: 1rem;
}

.promo-content p {
  font-size: 1.0625rem;
  color: var(--color-gray-500);
  margin-bottom: 1.5rem;
  max-width: 480px;
}

@media (min-width: 768px) {
  .promo-block {
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
  }
}

/* ============================================
   Grid Layouts
   ============================================ */

.grid-2 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

.grid-3 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

.grid-4 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 640px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 768px) {
  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* ============================================
   Tabs
   ============================================ */

.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 2rem;
  justify-content: center;
}

.tab-btn {
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-gray-500);
  background: var(--color-white);
  border: 1.5px solid var(--color-gray-200);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.tab-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.tab-btn.active {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================
   Carousel
   ============================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: 1rem;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  flex: 0 0 calc(100% - 1rem);
  min-width: 0;
}

@media (min-width: 640px) {
  .carousel-slide {
    flex: 0 0 calc(50% - 0.5rem);
  }
}

@media (min-width: 1024px) {
  .carousel-slide {
    flex: 0 0 calc(33.333% - 0.667rem);
  }
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1.5px solid var(--color-gray-200);
  color: var(--color-gray-700);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  cursor: pointer;
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.carousel-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: background var(--transition-fast);
  cursor: pointer;
  border: none;
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: var(--radius-full);
}

/* ============================================
   Gift Card Styles
   ============================================ */

.gift-card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.gift-card-media {
  aspect-ratio: 3 / 2;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.gift-card-title {
  padding: 1rem;
  font-size: 0.9375rem;
  font-weight: 600;
  text-align: center;
  color: var(--color-gray-800);
}

/* ============================================
   Store Locator
   ============================================ */

.locator-bar {
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
  padding: 1.25rem 0;
}

.locator-bar-inner {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
}

.toggle-group {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-gray-500);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.toggle-btn.active {
  background: var(--color-white);
  color: var(--color-gray-900);
  box-shadow: var(--shadow-sm);
}

.search-field {
  position: relative;
  flex: 1;
  min-width: 240px;
}

.search-field input {
  width: 100%;
  padding: 0.625rem 1rem 0.625rem 2.75rem;
  font-size: 0.9375rem;
  border: 1.5px solid var(--color-gray-200);
  border-radius: var(--radius-full);
  background: var(--color-white);
  transition: border-color var(--transition-fast);
  outline: none;
}

.search-field input:focus {
  border-color: var(--color-primary);
}

.search-field svg {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-gray-400);
  pointer-events: none;
}

.filter-panel {
  display: none;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-top: 1rem;
  box-shadow: var(--shadow-lg);
}

.filter-panel.open {
  display: block;
  animation: fadeIn 0.2s ease;
}

.map-container {
  height: 400px;
  background: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.map-placeholder {
  text-align: center;
  color: var(--color-gray-500);
}

.map-pin {
  position: absolute;
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
}

.map-pin::after {
  content: '';
  width: 12px;
  height: 12px;
  background: var(--color-white);
  border-radius: 50%;
}

.store-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  transition: box-shadow var(--transition-fast);
}

.store-card:hover {
  box-shadow: var(--shadow-md);
}

.store-card h4 {
  font-size: 1rem;
  margin-bottom: 0.25rem;
}

.store-card p {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 0.75rem;
}

.store-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.store-tag {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.625rem;
  background: var(--color-gray-100);
  color: var(--color-gray-600);
  border-radius: var(--radius-full);
}

/* ============================================
   Menu Page
   ============================================ */

.menu-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 1024px) {
  .menu-layout {
    grid-template-columns: 260px 1fr;
  }
}

.menu-sidebar {
  position: sticky;
  top: 80px;
  height: fit-content;
}

.menu-sidebar-group {
  margin-bottom: 1.5rem;
}

.menu-sidebar-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-gray-400);
  margin-bottom: 0.75rem;
}

.menu-sidebar ul {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.menu-sidebar a {
  display: block;
  padding: 0.5rem 0.75rem;
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.menu-sidebar a:hover,
.menu-sidebar a.active {
  background: var(--color-gray-100);
  color: var(--color-primary);
}

.menu-category {
  margin-bottom: 3rem;
}

.menu-category h3 {
  font-size: 1.5rem;
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 2px solid var(--color-gray-100);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

@media (min-width: 768px) {
  .menu-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .menu-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.menu-item {
  text-align: center;
  padding: 1rem;
  border-radius: var(--radius-lg);
  transition: background var(--transition-fast);
}

.menu-item:hover {
  background: var(--color-gray-50);
}

.menu-item-img {
  width: 100%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-cream) 0%, var(--color-gray-200) 100%);
  margin-bottom: 0.75rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  overflow: hidden;
}

.menu-item-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-gray-800);
}

/* ============================================
   Rewards Page
   ============================================ */

.tier-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
